  var initApi = (signingKey) => {
    window.signApi = {
      signRawPromise: async (address, message) => {
        try {
          return await firstValueFrom(Q_e.accounts$.pipe(
            take(1),
            map((sgnrs) => findAccount(sgnrs, address)),
            switchMap(async (signer) => {
              if (!signer) {
                throw Error("signer not found addr=" + address);
              }
              return await signingKey.signRaw({
                address: signer.address,
                data: message.startsWith("0x") ? message : stringToHex(message),
                type: "bytes"
              });
            })
          ));
        } catch (e) {
          return { error: e.message };
        }
      },
      signPayloadPromise: async (address, payload) => {
        try {
          return await firstValueFrom(Q_e.accounts$.pipe(
            take(1),
            map((sgnrs) => findAccount(sgnrs, address)),
            switchMap((signer) => {
              if (!signer) {
                throw Error("signer not found addr=" + address);
              }
              return signingKey.signPayload(payload);
            })
          ));
        } catch (e) {
          return { error: e.message };
        }
      }
    };
  };

